//! Expression evaluation: lexing, conversion to postfix and evaluation.

use std::fmt;

/// Unit used by the trigonometric functions.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum AngleUnit {
    Degree,
    Radian,
    Gradian,
}

/// Global calculation settings.
#[derive(Clone, Copy, Debug)]
pub struct Settings {
    pub fix: usize,
    pub base: u32,
    pub angle: AngleUnit,
}

#[derive(Clone, Debug, PartialEq)]
pub enum CalcError {
    Syntax(String),
    Parser(String),
    DivideByZero,
    Domain,
    TooLarge,
}

impl fmt::Display for CalcError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            CalcError::Syntax(m) => write!(f, "Syntax Error: {}", m),
            CalcError::Parser(m) => write!(f, "Parser Error: {}", m),
            CalcError::DivideByZero => write!(f, "Math Error: Divide by zero error!"),
            CalcError::Domain => write!(f, "Domain Error: Out of bounds!"),
            CalcError::TooLarge => write!(
                f,
                "Error: to large to process! Max value: {}",
                f64::MAX
            ),
        }
    }
}

fn mismatched() -> CalcError {
    CalcError::Syntax("Mismatched parentheses!".to_string())
}

fn too_few_operands() -> CalcError {
    CalcError::Parser("Too many operators, too few operands".to_string())
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum OpKind {
    Add,
    Sub,
    Mul,
    Div,
    Rem,
    Pow,
    Fact,
    /// Multiplication produced by a unary sign; binds tighter than anything.
    Sign,
}

impl OpKind {
    fn precedence(self) -> u8 {
        match self {
            OpKind::Add | OpKind::Sub => 2,
            OpKind::Mul | OpKind::Div | OpKind::Rem => 3,
            OpKind::Pow => 4,
            OpKind::Fact => 5,
            OpKind::Sign => 6,
        }
    }

    fn left_assoc(self) -> bool {
        !matches!(self, OpKind::Pow)
    }

    fn is_postfix(self) -> bool {
        matches!(self, OpKind::Fact)
    }
}

#[derive(Clone, Debug, PartialEq)]
pub enum Token {
    Num(f64),
    Op(OpKind),
    Func(Func),
    LParen,
    RParen,
    Comma,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Func {
    Sin,
    Cos,
    Tan,
    Csc,
    Sec,
    Cot,
    Sinh,
    Cosh,
    Tanh,
    Asin,
    Acos,
    Atan,
    Acsc,
    Asec,
    Acot,
    Ln,
    Log2,
    Log10,
    Sqrt,
    Ceil,
    Floor,
    Abs,
    Exp,
    Exp2,
    Round,
    Deg,
    Rad,
    Log,
    Nroot,
}

/// Names of every known function together with its identifier.
pub const FUNCTIONS: &[(&str, Func)] = &[
    ("sin", Func::Sin),
    ("cos", Func::Cos),
    ("tan", Func::Tan),
    ("csc", Func::Csc),
    ("sec", Func::Sec),
    ("cot", Func::Cot),
    ("sinh", Func::Sinh),
    ("cosh", Func::Cosh),
    ("tanh", Func::Tanh),
    ("asin", Func::Asin),
    ("acos", Func::Acos),
    ("atan", Func::Atan),
    ("acsc", Func::Acsc),
    ("asec", Func::Asec),
    ("acot", Func::Acot),
    ("ln", Func::Ln),
    ("log2", Func::Log2),
    ("log10", Func::Log10),
    ("sqrt", Func::Sqrt),
    ("ceil", Func::Ceil),
    ("floor", Func::Floor),
    ("abs", Func::Abs),
    ("exp", Func::Exp),
    ("exp2", Func::Exp2),
    ("round", Func::Round),
    ("deg", Func::Deg),
    ("rad", Func::Rad),
    ("log", Func::Log),
    ("nroot", Func::Nroot),
];

/// Known constants.
pub const CONSTANTS: &[(&str, f64)] = &[("e", std::f64::consts::E), ("pi", std::f64::consts::PI)];

fn lookup_function(name: &str) -> Option<Func> {
    FUNCTIONS.iter().find(|(n, _)| *n == name).map(|(_, f)| *f)
}

fn lookup_constant(name: &str) -> Option<f64> {
    CONSTANTS.iter().find(|(n, _)| *n == name).map(|(_, v)| *v)
}

fn is_function_prefix(s: &str) -> bool {
    FUNCTIONS.iter().any(|(n, _)| n.starts_with(s))
}

impl Func {
    fn arity(self) -> usize {
        match self {
            Func::Log | Func::Nroot => 2,
            _ => 1,
        }
    }

    fn apply(self, args: &[f64], angle: AngleUnit) -> f64 {
        let to_rad = |x: f64| match angle {
            AngleUnit::Radian => x,
            AngleUnit::Degree | AngleUnit::Gradian => x.to_radians(),
        };
        let x = args[0];
        match self {
            Func::Sin => to_rad(x).sin(),
            Func::Cos => to_rad(x).cos(),
            Func::Tan => to_rad(x).tan(),
            Func::Csc => 1.0 / to_rad(x).sin(),
            Func::Sec => 1.0 / to_rad(x).cos(),
            Func::Cot => 1.0 / to_rad(x).tan(),
            Func::Sinh => x.sinh(),
            Func::Cosh => x.cosh(),
            Func::Tanh => x.tanh(),
            Func::Asin => x.asin(),
            Func::Acos => x.acos(),
            Func::Atan => x.atan(),
            Func::Acsc => (1.0 / x).asin(),
            Func::Asec => (1.0 / x).acos(),
            Func::Acot => (1.0 / x).atan(),
            Func::Ln => x.ln(),
            Func::Log2 => x.log2(),
            Func::Log10 => x.log10(),
            Func::Sqrt => x.sqrt(),
            Func::Ceil => x.ceil(),
            Func::Floor => x.floor(),
            Func::Abs => x.abs(),
            Func::Exp => x.exp(),
            Func::Exp2 => x.exp2(),
            Func::Round => x.round(),
            Func::Deg => x.to_degrees(),
            Func::Rad => x.to_radians(),
            Func::Log => x.log(args[1]),
            Func::Nroot => x.powf(1.0 / args[1]),
        }
    }
}

/// Count parentheses and close any that were left open.
pub fn autobalance_parens(input: &str) -> Result<String, CalcError> {
    let mut balance: i64 = 0;
    for c in input.chars() {
        if c == '(' {
            balance += 1;
        } else if c == ')' {
            balance -= 1;
        }
    }
    if balance < 0 {
        return Err(mismatched());
    }
    let mut out = String::with_capacity(input.len() + balance as usize);
    out.push_str(input);
    for _ in 0..balance {
        out.push(')');
    }
    Ok(out)
}

struct Lexer {
    num_vec: String,
    char_vec: String,
    result: Vec<Token>,
    last_char_is_op: bool,
}

impl Lexer {
    /// Push the pending number if it parses; an unparsable number stays pending.
    fn flush_num(&mut self) -> bool {
        if self.num_vec.is_empty() {
            return false;
        }
        match self.num_vec.parse::<f64>() {
            Ok(x) => {
                self.result.push(Token::Num(x));
                self.num_vec.clear();
                true
            }
            Err(_) => false,
        }
    }

    /// Push the pending identifier if it is a known constant.
    fn flush_const(&mut self) -> bool {
        if let Some(v) = lookup_constant(&self.char_vec) {
            self.result.push(Token::Num(v));
            self.char_vec.clear();
            true
        } else {
            false
        }
    }

    fn flush(&mut self) {
        self.flush_const();
        self.flush_num();
    }
}

pub fn lex(input: &str, prev_ans: Option<f64>) -> Result<Vec<Token>, CalcError> {
    let mut lx = Lexer {
        num_vec: String::new(),
        char_vec: String::new(),
        result: Vec::new(),
        last_char_is_op: true,
    };
    let chars: Vec<char> = input.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        match c {
            '0'..='9' | '.' => {
                if !lx.char_vec.is_empty() {
                    if lx.flush_const() {
                        lx.result.push(Token::Op(OpKind::Mul));
                    } else {
                        let mut cand = lx.char_vec.clone();
                        cand.push(c);
                        if is_function_prefix(&cand) {
                            lx.char_vec = cand;
                            i += 1;
                            continue;
                        }
                        if lookup_function(&lx.char_vec).is_some() {
                            return Err(CalcError::Syntax(format!(
                                "Function '{}' expected parentheses",
                                lx.char_vec
                            )));
                        }
                        return Err(CalcError::Syntax(format!(
                            "Unexpected character '{}'",
                            cand
                        )));
                    }
                }
                lx.num_vec.push(c);
                lx.last_char_is_op = false;
            }
            'a'..='z' | 'A'..='Z' => {
                if lx.flush_num() {
                    lx.result.push(Token::Op(OpKind::Mul));
                }
                lx.char_vec.push(c);
                lx.last_char_is_op = false;
            }
            '_' => {
                let ans = match prev_ans {
                    Some(a) => a,
                    None => return Err(CalcError::Syntax("No previous answer!".to_string())),
                };
                if !lx.char_vec.is_empty() {
                    if lookup_function(&lx.char_vec).is_some() {
                        return Err(CalcError::Syntax(format!(
                            "Function '{}' expected parentheses",
                            lx.char_vec
                        )));
                    }
                    return Err(CalcError::Syntax(format!(
                        "Unexpected character '{}'",
                        lx.char_vec
                    )));
                }
                if lx.flush_num() {
                    lx.result.push(Token::Op(OpKind::Mul));
                }
                lx.result.push(Token::Num(ans));
                lx.last_char_is_op = false;
            }
            '(' => {
                if !lx.char_vec.is_empty() {
                    match lookup_function(&lx.char_vec) {
                        Some(f) => {
                            lx.result.push(Token::Func(f));
                            lx.char_vec.clear();
                        }
                        None => {
                            return Err(CalcError::Syntax(format!(
                                "Unknown function '{}'",
                                lx.char_vec
                            )))
                        }
                    }
                } else if !lx.num_vec.is_empty() {
                    lx.flush_num();
                    lx.result.push(Token::Op(OpKind::Mul));
                } else if let Some(Token::RParen) = lx.result.last() {
                    lx.result.push(Token::Op(OpKind::Mul));
                }
                lx.result.push(Token::LParen);
                lx.last_char_is_op = true;
            }
            ')' => {
                lx.flush();
                lx.result.push(Token::RParen);
                lx.last_char_is_op = false;
            }
            ',' => {
                lx.flush();
                lx.result.push(Token::Comma);
            }
            '+' | '-' => {
                lx.flush();
                if lx.last_char_is_op {
                    lx.result
                        .push(Token::Num(if c == '-' { -1.0 } else { 1.0 }));
                    lx.result.push(Token::Op(OpKind::Sign));
                } else {
                    lx.result.push(Token::Op(if c == '-' {
                        OpKind::Sub
                    } else {
                        OpKind::Add
                    }));
                    lx.last_char_is_op = true;
                }
            }
            '*' | '/' | '%' | '^' | '!' => {
                lx.flush();
                let kind = match c {
                    '*' => {
                        if i + 1 < chars.len() && chars[i + 1] == '*' {
                            i += 1;
                            OpKind::Pow
                        } else {
                            OpKind::Mul
                        }
                    }
                    '/' => OpKind::Div,
                    '%' => OpKind::Rem,
                    '^' => OpKind::Pow,
                    _ => OpKind::Fact,
                };
                lx.result.push(Token::Op(kind));
                lx.last_char_is_op = kind != OpKind::Fact;
            }
            _ => {
                return Err(CalcError::Syntax(format!("Unexpected token: '{}'", c)));
            }
        }
        i += 1;
    }
    lx.flush();
    Ok(lx.result)
}

/// Marker kept on the operator stack.
#[derive(Clone, Debug, PartialEq)]
enum StackItem {
    Op(OpKind),
    Func(Func),
    LParen,
}

pub fn to_postfix(tokens: Vec<Token>) -> Result<Vec<Token>, CalcError> {
    let mut out: Vec<Token> = Vec::with_capacity(tokens.len());
    let mut stack: Vec<StackItem> = Vec::new();
    let mut prev_was_comma = false;
    for tok in tokens {
        let is_comma = tok == Token::Comma;
        match tok {
            Token::Num(_) => out.push(tok),
            Token::Func(f) => stack.push(StackItem::Func(f)),
            Token::LParen => stack.push(StackItem::LParen),
            Token::Op(cur) => {
                while let Some(StackItem::Op(top)) = stack.last() {
                    let top = *top;
                    let tp = top.precedence();
                    let cp = cur.precedence();
                    if tp > cp || (tp == cp && cur.left_assoc()) {
                        out.push(Token::Op(top));
                        stack.pop();
                    } else {
                        break;
                    }
                }
                stack.push(StackItem::Op(cur));
            }
            Token::RParen => {
                let mut found = false;
                while let Some(item) = stack.pop() {
                    match item {
                        StackItem::LParen => {
                            found = true;
                            break;
                        }
                        StackItem::Op(o) => out.push(Token::Op(o)),
                        StackItem::Func(f) => out.push(Token::Func(f)),
                    }
                }
                if !found {
                    return Err(mismatched());
                }
                if let Some(StackItem::Func(f)) = stack.last() {
                    out.push(Token::Func(*f));
                    stack.pop();
                }
            }
            Token::Comma => {
                if prev_was_comma {
                    return Err(CalcError::Syntax("Empty argument".to_string()));
                }
                loop {
                    match stack.last() {
                        Some(StackItem::LParen) => break,
                        Some(StackItem::Op(o)) => {
                            out.push(Token::Op(*o));
                            stack.pop();
                        }
                        Some(StackItem::Func(f)) => {
                            out.push(Token::Func(*f));
                            stack.pop();
                        }
                        None => return Err(mismatched()),
                    }
                }
                // A separator is only meaningful for a function call (or the
                // outermost group); otherwise the group's paren is lost and the
                // closing paren will not find its partner.
                let n = stack.len();
                if n >= 2 && !matches!(stack[n - 2], StackItem::Func(_)) {
                    stack.pop();
                }
            }
        }
        prev_was_comma = is_comma;
    }
    while let Some(item) = stack.pop() {
        match item {
            StackItem::LParen => return Err(mismatched()),
            StackItem::Op(o) => out.push(Token::Op(o)),
            StackItem::Func(f) => out.push(Token::Func(f)),
        }
    }
    Ok(out)
}

fn checked(x: f64) -> Result<f64, CalcError> {
    if x.is_finite() {
        Ok(x)
    } else {
        Err(CalcError::TooLarge)
    }
}

fn factorial(x: f64) -> Result<f64, CalcError> {
    if x.fract() != 0.0 || x < 0.0 {
        return Err(CalcError::Domain);
    }
    let n = x as u64;
    let mut acc = 1.0f64;
    let mut i: u64 = 1;
    while i <= n {
        acc *= i as f64;
        i += 1;
    }
    Ok(acc)
}

pub fn eval_postfix(tokens: &[Token], settings: &Settings) -> Result<f64, CalcError> {
    let mut stack: Vec<f64> = Vec::new();
    for tok in tokens {
        match tok {
            Token::Num(x) => stack.push(*x),
            Token::Op(op) => {
                if op.is_postfix() {
                    let x = stack.pop().ok_or_else(too_few_operands)?;
                    let r = factorial(x)?;
                    stack.push(checked(r)?);
                } else {
                    if stack.len() < 2 {
                        return Err(too_few_operands());
                    }
                    let b = stack.pop().unwrap();
                    let a = stack.pop().unwrap();
                    let r = match op {
                        OpKind::Add => a + b,
                        OpKind::Sub => a - b,
                        OpKind::Mul | OpKind::Sign => a * b,
                        OpKind::Div => {
                            if b == 0.0 {
                                return Err(CalcError::DivideByZero);
                            }
                            a / b
                        }
                        OpKind::Rem => a % b,
                        OpKind::Pow => a.powf(b),
                        OpKind::Fact => unreachable!(),
                    };
                    stack.push(checked(r)?);
                }
            }
            Token::Func(f) => {
                let n = f.arity();
                if stack.len() < n {
                    return Err(CalcError::Parser(format!(
                        "To few arguments for function, need {}",
                        n
                    )));
                }
                let args = stack.split_off(stack.len() - n);
                let r = f.apply(&args, settings.angle);
                if !r.is_finite() {
                    return Err(CalcError::Domain);
                }
                stack.push(r);
            }
            Token::LParen | Token::RParen | Token::Comma => {
                return Err(mismatched());
            }
        }
    }
    if stack.len() == 1 {
        Ok(stack[0])
    } else {
        Err(too_few_operands())
    }
}

/// Round a value to the configured number of decimal places.
pub fn round_to_fix(x: f64, fix: usize) -> f64 {
    let s = format!("{:.*}", fix, x);
    s.parse::<f64>().unwrap_or(x)
}

/// Evaluate a full expression string.
pub fn eval_math_expression(
    input: &str,
    prev_ans: Option<f64>,
    settings: &Settings,
) -> Result<f64, CalcError> {
    let input = input.trim().replace(' ', "");
    if input.is_empty() {
        return Ok(0.0);
    }
    let input = autobalance_parens(&input)?;
    let lexed = lex(&input, prev_ans)?;
    let postfixed = to_postfix(lexed)?;
    let evaled = eval_postfix(&postfixed, settings)?;
    Ok(round_to_fix(evaled, settings.fix))
}
EOF"}

