//! Output formatting of results.

const DIGITS: &[u8] = b"0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ";

/// Insert thousands separators into the integral part of a number string.
pub fn thousands_sep(s: &str) -> String {
    let (sign, rest) = match s.strip_prefix('-') {
        Some(r) => ("-", r),
        None => ("", s),
    };
    let (int, frac) = match rest.find('.') {
        Some(i) => (&rest[..i], &rest[i..]),
        None => (rest, ""),
    };
    let chars: Vec<char> = int.chars().collect();
    let mut grouped = String::with_capacity(int.len() + int.len() / 3 + 1);
    let n = chars.len();
    for (i, c) in chars.iter().enumerate() {
        if i > 0 && (n - i) % 3 == 0 {
            grouped.push(',');
        }
        grouped.push(*c);
    }
    format!("{}{}{}", sign, grouped, frac)
}

/// Convert an integral, non-negative float to the digits of the given radix.
fn integral_digits(x: f64, radix: u32) -> String {
    if x == 0.0 {
        return "0".to_string();
    }
    // Decompose into mantissa * 2^exp exactly.
    let bits = x.to_bits();
    let exp_bits = ((bits >> 52) & 0x7ff) as i64;
    let mut mantissa = bits & ((1u64 << 52) - 1);
    let exp: i64;
    if exp_bits == 0 {
        exp = -1074;
    } else {
        mantissa |= 1u64 << 52;
        exp = exp_bits - 1075;
    }
    // Build a big integer (little-endian u32 limbs).
    let mut limbs: Vec<u32> = vec![mantissa as u32, (mantissa >> 32) as u32];
    if exp >= 0 {
        let shift = exp as usize;
        let word_shift = shift / 32;
        let bit_shift = shift % 32;
        let mut shifted = vec![0u32; word_shift];
        let mut carry: u32 = 0;
        for &l in &limbs {
            if bit_shift == 0 {
                shifted.push(l);
            } else {
                shifted.push((l << bit_shift) | carry);
                carry = l >> (32 - bit_shift);
            }
        }
        if carry != 0 {
            shifted.push(carry);
        }
        limbs = shifted;
    } else {
        // x is integral, so shifting right drops only zero bits.
        let shift = (-exp) as u32;
        let m = if shift >= 64 { 0 } else { mantissa >> shift };
        limbs = vec![m as u32, (m >> 32) as u32];
    }
    while limbs.len() > 1 && *limbs.last().unwrap() == 0 {
        limbs.pop();
    }
    let mut digits: Vec<u8> = Vec::new();
    let r = radix as u64;
    loop {
        let is_zero = limbs.iter().all(|&l| l == 0);
        if is_zero {
            break;
        }
        let mut rem: u64 = 0;
        for l in limbs.iter_mut().rev() {
            let cur = (rem << 32) | (*l as u64);
            *l = (cur / r) as u32;
            rem = cur % r;
        }
        digits.push(DIGITS[rem as usize]);
        while limbs.len() > 1 && *limbs.last().unwrap() == 0 {
            limbs.pop();
        }
    }
    digits.reverse();
    String::from_utf8(digits).unwrap()
}

/// Format a value in a radix other than ten.
fn radix_fmt(x: f64, radix: u32, fix: usize) -> String {
    let negative = x.is_sign_negative();
    let a = x.abs();
    let int = a.trunc();
    let mut frac = a - int;
    let mut int_str = String::new();
    if negative {
        int_str.push('-');
    }
    int_str.push_str(&integral_digits(int, radix));
    let padded = format!("{:>10}", int_str);
    let mut out = thousands_sep(&padded);
    out.push('.');
    for _ in 0..fix {
        frac *= radix as f64;
        let d = frac.trunc();
        out.push(DIGITS[d as usize] as char);
        frac -= d;
        if frac == 0.0 {
            break;
        }
    }
    out
}

/// Render a result the way it is printed to the user.
pub fn pprint(ans: f64, fix: usize, base: u32) -> String {
    if base == 10 || !ans.is_finite() {
        return thousands_sep(&format!("{:.*}", fix, ans));
    }
    let rounded = format!("{:.*}", fix, ans).parse::<f64>().unwrap_or(ans);
    radix_fmt(rounded, base, fix)
}
EOF"}

