        if is_zero {
            break;
        }
        let mut rem: u64 = 0;
        for l in limbs.iter_mut().rev() {
            let cur = (rem << 32) | (*l as u64);
            *l = (cur / r) as u32;
            rem = cur % r;
        }
        digits.push(DIGITS[rem as usize]);
        while limbs.len() > 1 && *limbs.last().unwrap() == 0 {
            limbs.pop();
        }
    }
    digits.reverse();
    String::from_utf8(digits).unwrap()
}

/// Format a value in a radix other than ten.
fn radix_fmt(x: f64, radix: u32, fix: usize) -> String {
    let negative = x.is_sign_negative();
    let a = x.abs();
    let int = a.trunc();
    let mut frac = a - int;
    let mut int_str = String::new();
    if negative {
        int_str.push('-');
    }
    int_str.push_str(&integral_digits(int, radix));
    let padded = format!("{:>10}", int_str);
    let mut out = thousands_sep(&padded);
    out.push('.');
    for _ in 0..fix {
        frac *= radix as f64;
        let d = frac.trunc();
        out.push(DIGITS[d as usize] as char);
        frac -= d;
        if frac == 0.0 {
            break;
        }
    }
    out
}

/// Render a result the way it is printed to the user.
pub fn pprint(ans: f64, fix: usize, base: u32) -> String {
    if base == 10 || !ans.is_finite() {
        return thousands_sep(&format!("{:.*}", fix, ans));
    }
    let rounded = format!("{:.*}", fix, ans).parse::<f64>().unwrap_or(ans);
    radix_fmt(rounded, base, fix)
}
