    use std::os::unix::ffi::OsStringExt;
    unsafe {
        let amt = match sysconf(SC_GETPW_R_SIZE_MAX) {
            n if n < 0 => 512usize,
            n => n as usize,
        };
        let mut buf: Vec<c_char> = Vec::with_capacity(amt);
        let mut pw: passwd = std::mem::zeroed();
        let mut result: *mut passwd = std::ptr::null_mut();
