        .or_else(|| home_dir().map(|h| h.join(fallback)))
}

pub fn data_dir() -> Option<PathBuf> {
    xdg_dir("XDG_DATA_HOME", ".local/share")
}

pub fn cache_dir() -> Option<PathBuf> {
    xdg_dir("XDG_CACHE_HOME", ".cache")
}

/// `<base>/eva/<file>`, falling back to `<home>/<file>` when the directory
/// cannot be created.
fn eva_file(base: Option<PathBuf>, file: &str) -> PathBuf {
    if let Some(mut dir) = base {
        dir.push("eva");
        if fs::create_dir_all(&dir).is_ok() {
            dir.push(file);
            return dir;
        }
    }
    let mut p = home_dir().unwrap_or_default();
    p.push(file);
    p
}

pub fn history_path() -> PathBuf {
    eva_file(data_dir(), "history.txt")
}

pub fn previous_ans_path() -> PathBuf {
    eva_file(cache_dir(), "previous_ans.txt")
}

/// File consulted by the syntax highlighter for the previous answer.
pub fn highlight_ans_path() -> PathBuf {
    eva_file(data_dir(), "previous_ans.txt")
}
