//! Persistent line history (compatible with the "#V2" history file format).

use std::collections::VecDeque;
use std::fs::File;
use std::io::{self, BufRead, BufReader, BufWriter, Write};
use std::path::Path;

const HEADER: &str = "#V2";

pub struct History {
    pub entries: VecDeque<String>,
    max_len: usize,
    ignore_space: bool,
    ignore_dups: bool,
    new_entries: usize,
}

impl History {
    pub fn new(max_len: usize) -> History {
        History {
            entries: VecDeque::new(),
            max_len,
            ignore_space: true,
            ignore_dups: true,
            new_entries: 0,
        }
    }

    pub fn len(&self) -> usize {
        self.entries.len()
    }

    pub fn get(&self, i: usize) -> Option<&String> {
        self.entries.get(i)
    }

    fn insert(&mut self, line: &str) -> bool {
        if self.max_len == 0 {
            return false;
        }
        if line.is_empty()
            || (self.ignore_space && line.chars().next().map_or(true, char::is_whitespace))
        {
            return false;
        }
        if self.ignore_dups {
            if let Some(last) = self.entries.back() {
                if last == line {
                    return false;
                }
            }
        }
        if self.entries.len() == self.max_len {
            self.entries.pop_front();
        }
        self.entries.push_back(line.to_string());
        true
    }

    pub fn add(&mut self, line: &str) -> bool {
        let added = self.insert(line);
        if added {
            self.new_entries = self.new_entries.saturating_add(1);
        }
        added
    }

    pub fn load(&mut self, path: &Path) -> io::Result<()> {
        let file = File::open(path)?;
        let rdr = BufReader::new(file);
        let mut lines = rdr.lines();
        let mut v2 = false;
        if let Some(first) = lines.next() {
            let line = first?;
            if line == HEADER {
                v2 = true;
            } else {
                self.insert(&line);
            }
        }
        for line in lines {
            let line = line?;
            if line.is_empty() {
                continue;
            }
            if v2 {
                self.insert(&unescape(&line));
            } else {
                self.insert(&line);
            }
        }
        self.new_entries = 0;
        Ok(())
    }

    pub fn save(&mut self, path: &Path) -> io::Result<()> {
        if self.entries.is_empty() || self.new_entries == 0 {
            return Ok(());
        }
        let old = unsafe { crate::sys::umask(0o177) };
        let f = File::create(path);
        unsafe {
            crate::sys::umask(old);
        }
        let file = f?;
        let mut w = BufWriter::new(file);
        w.write_all(HEADER.as_bytes())?;
        w.write_all(b"\n")?;
        for entry in &self.entries {
            w.write_all(escape(entry).as_bytes())?;
            w.write_all(b"\n")?;
        }
        w.flush()?;
        self.new_entries = 0;
        Ok(())
    }

    /// Search backwards from `start` for an entry beginning with `term`.
    pub fn starts_with_reverse(&self, term: &str, start: usize) -> Option<usize> {
        if self.entries.is_empty() {
            return None;
        }
        let start = start.min(self.entries.len() - 1);
        (0..=start).rev().find(|&i| self.entries[i].starts_with(term))
    }

    /// Search for an entry containing `term` in the given direction.
    pub fn search(&self, term: &str, start: usize, reverse: bool) -> Option<(usize, usize)> {
        if self.entries.is_empty() || term.is_empty() {
            return None;
        }
        if start >= self.entries.len() {
            return None;
        }
        if reverse {
            for i in (0..=start).rev() {
                if let Some(p) = self.entries[i].rfind(term) {
                    return Some((i, p));
                }
            }
        } else {
            for i in start..self.entries.len() {
                if let Some(p) = self.entries[i].find(term) {
                    return Some((i, p));
                }
            }
        }
        None
    }
}

fn escape(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for c in s.chars() {
        match c {
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            _ => out.push(c),
        }
    }
    out
}

fn unescape(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    let mut chars = s.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '\\' {
            match chars.peek() {
                Some('\\') => {
                    out.push('\\');
                    chars.next();
                }
                Some('n') => {
                    out.push('\n');
                    chars.next();
                }
                _ => out.push(c),
            }
        } else {
            out.push(c);
        }
    }
    out
}
