//! Line reading for the REPL: a small emacs-style line editor for terminals
//! and plain line reading for pipes and unsupported terminals.

use crate::calc::{eval_math_expression, Settings, CONSTANTS, FUNCTIONS};
use crate::history::History;
use crate::sys;
use std::fs;
use std::io::{self, BufRead, Write};
use std::path::Path;

pub enum ReadResult {
    Line(String),
    Interrupted,
    Eof,
    Error(String),
}

const MAX_HISTORY: usize = 1000;
const TAB_STOP: usize = 8;

pub struct Editor {
    history: History,
    settings: Settings,
    kill_ring: String,
    stdin: io::StdinLock<'static>,
}

fn unsupported_term() -> bool {
    match std::env::var("TERM") {
        Ok(term) => ["dumb", "cons25", "emacs"]
            .iter()
            .any(|t| term.eq_ignore_ascii_case(t)),
        Err(_) => false,
    }
}

#[derive(Clone, Copy, Default, Debug, PartialEq)]
struct Position {
    col: usize,
    row: usize,
}

#[derive(Clone, Copy, Default, Debug)]
struct Layout {
    cursor: Position,
    end: Position,
}

/// Display width of a character on the terminal.
fn char_width(c: char) -> usize {
    let cp = c as u32;
    if cp < 0x20 || (0x7f..0xa0).contains(&cp) {
        return 0;
    }
    // Combining marks and zero width characters.
    if (0x300..=0x36f).contains(&cp)
        || (0x200b..=0x200f).contains(&cp)
        || (0x20d0..=0x20ff).contains(&cp)
        || (0xfe20..=0xfe2f).contains(&cp)
        || cp == 0xfeff
    {
        return 0;
    }
    if (0x1100..=0x115f).contains(&cp)
        || (0x2e80..=0x303e).contains(&cp)
        || (0x3041..=0x33ff).contains(&cp)
        || (0x3400..=0x4dbf).contains(&cp)
        || (0x4e00..=0x9fff).contains(&cp)
        || (0xa000..=0xa4cf).contains(&cp)
        || (0xac00..=0xd7a3).contains(&cp)
        || (0xf900..=0xfaff).contains(&cp)
        || (0xfe30..=0xfe4f).contains(&cp)
        || (0xff00..=0xff60).contains(&cp)
        || (0xffe0..=0xffe6).contains(&cp)
        || (0x1f300..=0x1f64f).contains(&cp)
        || (0x1f900..=0x1f9ff).contains(&cp)
        || (0x20000..=0x3fffd).contains(&cp)
    {
        return 2;
    }
    1
}

fn calculate_position(s: &str, orig: Position, cols: usize) -> Position {
    let mut pos = orig;
    for c in s.chars() {
        if c == '\n' {
            pos.row += 1;
            pos.col = 0;
            continue;
        }
        let cw = if c == '\t' {
            TAB_STOP - (pos.col % TAB_STOP)
        } else {
            char_width(c)
        };
        pos.col += cw;
        if pos.col > cols {
            pos.row += 1;
            pos.col = cw;
        }
    }
    if pos.col == cols {
        pos.col = 0;
        pos.row += 1;
    }
    pos
}

/// Syntax highlighting of an input line.
pub fn highlight(line: &str, settings: &Settings) -> String {
    let prev = read_highlight_ans();
    match eval_math_expression(line, prev, settings) {
        Err(_) => format!("\x1b[31m{}\x1b[0m", line),
        Ok(_) => colorize(line),
    }
}

fn read_highlight_ans() -> Option<f64> {
    let path = crate::paths::highlight_ans_path();
    let mut content = String::new();
    if let Ok(mut f) = fs::OpenOptions::new()
        .read(true)
        .write(true)
        .create(true)
        .truncate(false)
        .open(&path)
    {
        use std::io::Read;
        let _ = f.read_to_string(&mut content);
    }
    content.trim().parse::<f64>().ok()
}

fn is_op_char(c: char) -> bool {
    matches!(c, '+' | ',' | '-' | '.' | '/' | '*' | '%' | '^' | '!')
}

/// Wrap occurrences of `word` followed by one of the accepted terminators.
fn wrap_word(s: &str, word: &str, color: &str, terminator: fn(&str) -> bool) -> String {
    let mut out = String::with_capacity(s.len() + 16);
    let mut i = 0;
    let bytes = s.as_bytes();
    while i < s.len() {
        if s[i..].starts_with(word) && terminator(&s[i + word.len()..]) {
            out.push_str(color);
            out.push_str(word);
            out.push_str("\x1b[0m");
            i += word.len();
        } else {
            let ch_len = utf8_len(bytes[i]);
            out.push_str(&s[i..i + ch_len]);
            i += ch_len;
        }
    }
    out
}

fn utf8_len(b: u8) -> usize {
    if b < 0x80 {
        1
    } else if b >= 0xf0 {
        4
    } else if b >= 0xe0 {
        3
    } else if b >= 0xc0 {
        2
    } else {
        1
    }
}

fn const_terminator(rest: &str) -> bool {
    match rest.chars().next() {
        None => true,
        Some(c) => c == '\x1b' || c.is_whitespace(),
    }
}

fn func_terminator(rest: &str) -> bool {
    match rest.chars().next() {
        None => true,
        Some(c) => c == '(',
    }
}

fn colorize(line: &str) -> String {
    let mut coloured = String::with_capacity(line.len() * 2);
    for c in line.chars() {
        if is_op_char(c) {
            coloured.push_str("\x1b[35m");
            coloured.push(c);
            coloured.push_str("\x1b[0m");
        } else {
            coloured.push(c);
        }
    }
    for (name, _) in CONSTANTS {
        coloured = wrap_word(&coloured, name, "\x1b[33m", const_terminator);
    }
    // Longer names first so that e.g. "asin" wins over "sin".
    let mut names: Vec<&str> = FUNCTIONS.iter().map(|(n, _)| *n).collect();
    names.sort_by(|a, b| b.len().cmp(&a.len()));
    for name in names {
        coloured = wrap_word(&coloured, name, "\x1b[34m", func_terminator);
    }
    coloured
}

/// State of the line being edited.
struct LineState {
    line: String,
    pos: usize,
    old: Layout,
    hist_index: usize,
    saved: Option<String>,
}

enum Key {
    Char(char),
    Ctrl(char),
    Meta(char),
    MetaBackspace,
    Enter,
    Backspace,
    Tab,
    Esc,
    Left,
    Right,
    Up,
    Down,
    Home,
    End,
    Delete,
    CtrlLeft,
    CtrlRight,
    Paste(String),
    Unknown,
    Eof,
}

impl Editor {
    pub fn new(settings: Settings) -> Editor {
        Editor {
            history: History::new(MAX_HISTORY),
            settings,
            kill_ring: String::new(),
            stdin: io::stdin().lock(),
        }
    }

    pub fn load_history(&mut self, path: &Path) -> io::Result<()> {
        self.history.load(path)
    }

    pub fn save_history(&mut self, path: &Path) -> io::Result<()> {
        self.history.save(path)
    }

    pub fn add_history(&mut self, line: &str) {
        self.history.add(line);
    }

    pub fn readline(&mut self, prompt: &str) -> ReadResult {
        if unsupported_term() {
            let mut out = io::stdout();
            let _ = out.write_all(prompt.as_bytes());
            let _ = out.flush();
            return self.read_direct();
        }
        if sys::is_tty(0) {
            if let Some(orig) = sys::get_termios(0) {
                return self.read_tty(prompt, orig);
            }
        }
        self.read_direct()
    }

    fn read_direct(&mut self) -> ReadResult {
        let mut input = String::new();
        match self.stdin.read_line(&mut input) {
            Ok(0) => ReadResult::Eof,
            Ok(_) => {
                if input.ends_with('\n') {
                    input.pop();
                    if input.ends_with('\r') {
                        input.pop();
                    }
                }
                ReadResult::Line(input)
            }
            Err(e) => ReadResult::Error(format!("Io({:?})", e)),
        }
    }

    // ----------------------------------------------------------------------
    // Terminal editing

    fn read_tty(&mut self, prompt: &str, orig: sys::termios) -> ReadResult {
        let mut raw = orig;
        raw.c_iflag &= !(sys::BRKINT | sys::ICRNL | sys::INPCK | sys::ISTRIP | sys::IXON);
        raw.c_oflag &= !sys::OPOST;
        raw.c_cflag |= sys::CS8;
        raw.c_lflag &= !(sys::ECHO | sys::ICANON | sys::IEXTEN | sys::ISIG);
        raw.c_cc[sys::VMIN] = 1;
        raw.c_cc[sys::VTIME] = 0;
        sys::set_termios(0, &raw);
        let _ = io::stdout().flush();
        out_write("\x1b[?2004h");
        let result = self.edit(prompt, &raw);
        sys::set_termios(0, &orig);
        result
    }

    fn colors(&self) -> bool {
        sys::is_tty(1)
    }

    fn hint(&self, st: &LineState) -> Option<String> {
        if st.line.is_empty() || st.pos < st.line.len() {
            return None;
        }
        let len = self.history.len();
        let start = if st.hist_index == len {
            st.hist_index.saturating_sub(1)
        } else {
            st.hist_index
        };
        let idx = self.history.starts_with_reverse(&st.line, start)?;
        let entry = self.history.get(idx)?;
        if *entry == st.line {
            return None;
        }
        Some(entry[st.pos..].to_string())
    }

    fn render(&self, prompt: &str, st: &mut LineState, with_hint: bool) {
        let hint = if with_hint { self.hint(st) } else { None };
        let display = if self.colors() {
            highlight(&st.line, &self.settings)
        } else {
            st.line.clone()
        };
        self.render_text(prompt, &st.line, &display, st.pos, hint.as_deref(), &mut st.old);
    }

    fn render_text(
        &self,
        prompt: &str,
        line: &str,
        display: &str,
        pos: usize,
        hint: Option<&str>,
        old: &mut Layout,
    ) {
        let cols = sys::terminal_cols(1);
        let prompt_size = calculate_position(prompt, Position::default(), cols);
        let cursor = calculate_position(&line[..pos], prompt_size, cols);
        let mut end = if pos == line.len() {
            cursor
        } else {
            calculate_position(&line[pos..], cursor, cols)
        };
        if let Some(h) = hint {
            end = calculate_position(h, end, cols);
        }
        let mut buf = String::new();
        buf.push_str("\x1b[?2026h");
        let current_row = old.cursor.row;
        let old_rows = old.end.row;
        let cursor_row_movement = old_rows.saturating_sub(current_row);
        if cursor_row_movement > 0 {
            buf.push_str(&format!("\x1b[{}B", cursor_row_movement));
        }
        for _ in 0..old_rows {
            buf.push_str("\r\x1b[K\x1b[A");
        }
        buf.push_str("\r\x1b[K");
        buf.push_str(prompt);
        buf.push_str(display);
        if let Some(h) = hint {
            if self.colors() {
                buf.push_str("\x1b[90m");
                buf.push_str(h);
                buf.push_str("\x1b[0m");
            } else {
                buf.push_str(h);
            }
        }
        let ends_nl = match hint {
            Some(h) => h.ends_with('\n'),
            None => line.ends_with('\n'),
        };
        if end.col == 0 && end.row > 0 && !ends_nl {
            buf.push('\n');
        }
        let up = end.row.saturating_sub(cursor.row);
        if up > 0 {
            buf.push_str(&format!("\x1b[{}A", up));
        }
        if cursor.col > 0 {
            buf.push_str(&format!("\r\x1b[{}C", cursor.col));
        } else {
            buf.push('\r');
        }
        buf.push_str("\x1b[?2026l");
        out_write(&buf);
        *old = Layout { cursor, end };
    }

    fn read_key(&self) -> Key {
        let b = match sys::read_byte(0, -1) {
            Some(b) => b,
            None => return Key::Eof,
        };
        match b {
            0x1b => self.read_escape(),
            b'\r' | b'\n' => Key::Enter,
            0x7f | 0x08 => Key::Backspace,
            b'\t' => Key::Tab,
            0x00..=0x1f => Key::Ctrl((b + 0x40).to_ascii_lowercase() as char),
            _ => {
                let len = utf8_len(b);
                let mut bytes = vec![b];
                for _ in 1..len {
                    match sys::read_byte(0, -1) {
                        Some(c) => bytes.push(c),
                        None => break,
                    }
                }
                match std::str::from_utf8(&bytes) {
                    Ok(s) => Key::Char(s.chars().next().unwrap()),
                    Err(_) => Key::Unknown,
                }
            }
        }
    }

    fn read_escape(&self) -> Key {
        let b = match sys::read_byte(0, 50) {
            Some(b) => b,
            None => return Key::Esc,
        };
        match b {
            b'[' => self.read_csi(),
            b'O' => match sys::read_byte(0, 50) {
                Some(b'A') => Key::Up,
                Some(b'B') => Key::Down,
                Some(b'C') => Key::Right,
                Some(b'D') => Key::Left,
                Some(b'H') => Key::Home,
                Some(b'F') => Key::End,
                _ => Key::Unknown,
            },
            0x7f | 0x08 => Key::MetaBackspace,
            0x1b => Key::Esc,
            c if c >= 0x20 && c < 0x7f => Key::Meta(c as char),
            _ => Key::Unknown,
        }
    }

    fn read_csi(&self) -> Key {
        let mut params = String::new();
        let final_byte;
        loop {
            match sys::read_byte(0, 50) {
                Some(c) if (0x30..=0x3f).contains(&c) || c == b';' => params.push(c as char),
                Some(c) => {
                    final_byte = c;
                    break;
                }
                None => return Key::Unknown,
            }
        }
        match (params.as_str(), final_byte) {
            ("", b'A') => Key::Up,
            ("", b'B') => Key::Down,
            ("", b'C') => Key::Right,
            ("", b'D') => Key::Left,
            ("", b'H') | ("1", b'~') | ("7", b'~') => Key::Home,
            ("", b'F') | ("4", b'~') | ("8", b'~') => Key::End,
            ("3", b'~') => Key::Delete,
            ("1;5", b'C') | ("5C", _) => Key::CtrlRight,
            ("1;5", b'D') => Key::CtrlLeft,
            ("1;3", b'C') => Key::Meta('f'),
            ("1;3", b'D') => Key::Meta('b'),
            ("200", b'~') => Key::Paste(self.read_paste()),
            _ => Key::Unknown,
        }
    }

    fn read_paste(&self) -> String {
        let mut bytes: Vec<u8> = Vec::new();
        let end = b"\x1b[201~";
        loop {
            match sys::read_byte(0, -1) {
                Some(b) => {
                    bytes.push(b);
                    if bytes.ends_with(end) {
                        bytes.truncate(bytes.len() - end.len());
                        break;
                    }
                }
                None => break,
            }
        }
        let s = String::from_utf8_lossy(&bytes).into_owned();
        s.replace("\r\n", "\n").replace('\r', "\n")
    }

    fn edit(&mut self, prompt: &str, raw: &sys::termios) -> ReadResult {
        let mut st = LineState {
            line: String::new(),
            pos: 0,
            old: Layout::default(),
            hist_index: self.history.len(),
            saved: None,
        };
        self.render(prompt, &mut st, true);
        loop {
            let key = self.read_key();
            match key {
                Key::Eof => {
                    out_write("\x1b[?2004l\r\n");
                    return ReadResult::Eof;
                }
                Key::Enter => {
                    self.render(prompt, &mut st, false);
                    out_write("\x1b[?2004l\r\n");
                    return ReadResult::Line(st.line);
                }
                Key::Ctrl('c') => {
                    out_write("\x1b[?2004l\r\n");
                    return ReadResult::Interrupted;
                }
                Key::Ctrl('d') => {
                    if st.line.is_empty() {
                        self.render(prompt, &mut st, false);
                        out_write("\x1b[?2004l\r\n");
                        return ReadResult::Eof;
                    }
                    if st.pos < st.line.len() {
                        st.line.remove(st.pos);
                        self.render(prompt, &mut st, true);
                    }
                }
                Key::Delete => {
                    if st.pos < st.line.len() {
                        st.line.remove(st.pos);
                        self.render(prompt, &mut st, true);
                    }
                }
                Key::Char(c) => {
                    st.line.insert(st.pos, c);
                    st.pos += c.len_utf8();
                    self.render(prompt, &mut st, true);
                }
                Key::Paste(s) => {
                    st.line.insert_str(st.pos, &s);
                    st.pos += s.len();
                    self.render(prompt, &mut st, true);
                }
                Key::Backspace | Key::Ctrl('h') => {
                    if st.pos > 0 {
                        let p = prev_char_boundary(&st.line, st.pos);
                        st.line.replace_range(p..st.pos, "");
                        st.pos = p;
                        self.render(prompt, &mut st, true);
                    }
                }
                Key::Left | Key::Ctrl('b') => {
                    if st.pos > 0 {
                        st.pos = prev_char_boundary(&st.line, st.pos);
                        self.render(prompt, &mut st, true);
                    }
                }
                Key::Right => {
                    if st.pos < st.line.len() {
                        st.pos = next_char_boundary(&st.line, st.pos);
                        self.render(prompt, &mut st, true);
                    } else if let Some(h) = self.hint(&st) {
                        st.line.push_str(&h);
                        st.pos = st.line.len();
                        self.render(prompt, &mut st, true);
                    }
                }
                Key::Ctrl('f') => {
                    if st.pos < st.line.len() {
                        st.pos = next_char_boundary(&st.line, st.pos);
                        self.render(prompt, &mut st, true);
                    }
                }
                Key::Home | Key::Ctrl('a') => {
                    if st.pos > 0 {
                        st.pos = 0;
                        self.render(prompt, &mut st, true);
                    }
                }
                Key::End | Key::Ctrl('e') => {
                    if st.pos < st.line.len() {
                        st.pos = st.line.len();
                        self.render(prompt, &mut st, true);
                    }
                }
                Key::Up | Key::Ctrl('p') => {
                    if st.hist_index > 0 {
                        if st.hist_index == self.history.len() {
                            st.saved = Some(st.line.clone());
                        }
                        st.hist_index -= 1;
                        st.line = self.history.get(st.hist_index).cloned().unwrap_or_default();
                        st.pos = st.line.len();
                        self.render(prompt, &mut st, true);
                    }
                }
                Key::Down | Key::Ctrl('n') => {
                    if st.hist_index < self.history.len() {
                        st.hist_index += 1;
                        if st.hist_index == self.history.len() {
                            st.line = st.saved.take().unwrap_or_default();
                        } else {
                            st.line =
                                self.history.get(st.hist_index).cloned().unwrap_or_default();
                        }
                        st.pos = st.line.len();
                        self.render(prompt, &mut st, true);
                    }
                }
                Key::Meta('<') => {
                    if st.hist_index > 0 {
                        if st.hist_index == self.history.len() {
                            st.saved = Some(st.line.clone());
                        }
                        st.hist_index = 0;
                        st.line = self.history.get(0).cloned().unwrap_or_default();
                        st.pos = st.line.len();
                        self.render(prompt, &mut st, true);
                    }
                }
                Key::Meta('>') => {
                    if st.hist_index < self.history.len() {
                        st.hist_index = self.history.len();
                        st.line = st.saved.take().unwrap_or_default();
                        st.pos = st.line.len();
                        self.render(prompt, &mut st, true);
                    }
                }
                Key::Ctrl('k') => {
                    if st.pos < st.line.len() {
                        self.kill_ring = st.line[st.pos..].to_string();
                        st.line.truncate(st.pos);
                        self.render(prompt, &mut st, true);
                    }
                }
                Key::Ctrl('u') => {
                    if st.pos > 0 {
                        self.kill_ring = st.line[..st.pos].to_string();
                        st.line.replace_range(..st.pos, "");
                        st.pos = 0;
                        self.render(prompt, &mut st, true);
                    }
                }
                Key::Ctrl('w') => {
                    if st.pos > 0 {
                        let start = word_start(&st.line, st.pos, char::is_whitespace);
                        if start < st.pos {
                            self.kill_ring = st.line[start..st.pos].to_string();
                            st.line.replace_range(start..st.pos, "");
                            st.pos = start;
                            self.render(prompt, &mut st, true);
                        }
                    }
                }
                Key::MetaBackspace => {
                    if st.pos > 0 {
                        let start = word_start(&st.line, st.pos, |c| !c.is_alphanumeric());
                        if start < st.pos {
                            self.kill_ring = st.line[start..st.pos].to_string();
                            st.line.replace_range(start..st.pos, "");
                            st.pos = start;
                            self.render(prompt, &mut st, true);
                        }
                    }
                }
                Key::Meta('d') => {
                    let end = word_end(&st.line, st.pos);
                    if end > st.pos {
                        self.kill_ring = st.line[st.pos..end].to_string();
                        st.line.replace_range(st.pos..end, "");
                        self.render(prompt, &mut st, true);
                    }
                }
                Key::Meta('b') | Key::CtrlLeft => {
                    let start = word_start(&st.line, st.pos, |c| !c.is_alphanumeric());
                    if start < st.pos {
                        st.pos = start;
                        self.render(prompt, &mut st, true);
                    }
                }
                Key::Meta('f') | Key::CtrlRight => {
                    let end = word_end(&st.line, st.pos);
                    if end > st.pos {
                        st.pos = end;
                        self.render(prompt, &mut st, true);
                    }
                }
                Key::Ctrl('y') => {
                    if !self.kill_ring.is_empty() {
                        let k = self.kill_ring.clone();
                        st.line.insert_str(st.pos, &k);
                        st.pos += k.len();
                        self.render(prompt, &mut st, true);
                    }
                }
                Key::Ctrl('t') => {
                    if st.pos > 0 && st.line.chars().count() >= 2 {
                        let mut p = st.pos;
                        if p == st.line.len() {
                            p = prev_char_boundary(&st.line, p);
                        }
                        let a_start = prev_char_boundary(&st.line, p);
                        let b_end = next_char_boundary(&st.line, p);
                        let a: String = st.line[a_start..p].to_string();
                        let b: String = st.line[p..b_end].to_string();
                        st.line.replace_range(a_start..b_end, &format!("{}{}", b, a));
                        st.pos = b_end;
                        self.render(prompt, &mut st, true);
                    }
                }
                Key::Ctrl('l') => {
                    out_write("\x1b[H\x1b[J");
                    st.old = Layout::default();
                    self.render(prompt, &mut st, true);
                }
                Key::Ctrl('r') => {
                    if let Some(r) = self.reverse_search(prompt, &mut st) {
                        return r;
                    }
                }
                Key::Ctrl('z') => {
                    let orig_mode = sys::get_termios(0);
                    out_write("\x1b[?2004l");
                    if let Some(o) = orig_mode {
                        let _ = o;
                    }
                    unsafe {
                        sys::raise(sys::SIGTSTP);
                    }
                    sys::set_termios(0, raw);
                    out_write("\x1b[?2004h");
                    st.old = Layout::default();
                    self.render(prompt, &mut st, true);
                }
                Key::Tab => {
                    if let Some(r) = self.complete(prompt, &mut st) {
                        return r;
                    }
                }
                _ => {}
            }
        }
    }

    /// Incremental reverse history search (Ctrl-R).
    fn reverse_search(&mut self, prompt: &str, st: &mut LineState) -> Option<ReadResult> {
        let orig_line = st.line.clone();
        let orig_pos = st.pos;
        let mut query = String::new();
        let mut found_line = st.line.clone();
        let mut found_pos = st.pos;
        let mut found_idx: Option<usize> = None;
        let mut failed = false;
        let render = |ed: &Editor, st: &mut LineState, q: &str, failed: bool, l: &str, p: usize| {
            let sp = format!(
                "({}reverse-i-search)`{}': ",
                if failed { "failed " } else { "" },
                q
            );
            ed.render_text(&sp, l, l, p, None, &mut st.old);
        };
        render(self, st, &query, failed, &found_line, found_pos);
        loop {
            let key = self.read_key();
            match key {
                Key::Char(c) => {
                    query.push(c);
                    let start = found_idx.unwrap_or(self.history.len().saturating_sub(1));
                    match self.history.search(&query, start, true) {
                        Some((i, p)) => {
                            found_idx = Some(i);
                            found_line = self.history.get(i).cloned().unwrap_or_default();
                            found_pos = p;
                            failed = false;
                        }
                        None => failed = true,
                    }
                    render(self, st, &query, failed, &found_line, found_pos);
                }
                Key::Backspace => {
                    query.pop();
                    render(self, st, &query, failed, &found_line, found_pos);
                }
                Key::Ctrl('r') => {
                    let start = match found_idx {
                        Some(0) => {
                            failed = true;
                            render(self, st, &query, failed, &found_line, found_pos);
                            continue;
                        }
                        Some(i) => i - 1,
                        None => self.history.len().saturating_sub(1),
                    };
                    match self.history.search(&query, start, true) {
                        Some((i, p)) => {
                            found_idx = Some(i);
                            found_line = self.history.get(i).cloned().unwrap_or_default();
                            found_pos = p;
                            failed = false;
                        }
                        None => failed = true,
                    }
                    render(self, st, &query, failed, &found_line, found_pos);
                }
                Key::Ctrl('g') | Key::Esc => {
                    st.line = orig_line;
                    st.pos = orig_pos;
                    self.render(prompt, st, true);
                    return None;
                }
                Key::Ctrl('c') => {
                    out_write("\x1b[?2004l\r\n");
                    return Some(ReadResult::Interrupted);
                }
                Key::Eof => {
                    out_write("\x1b[?2004l\r\n");
                    return Some(ReadResult::Eof);
                }
                Key::Enter => {
                    st.line = found_line;
                    st.pos = found_pos;
                    if let Some(i) = found_idx {
                        st.hist_index = i;
                    }
                    self.render(prompt, st, false);
                    out_write("\x1b[?2004l\r\n");
                    return Some(ReadResult::Line(st.line.clone()));
                }
                other => {
                    st.line = found_line;
                    st.pos = found_pos;
                    if let Some(i) = found_idx {
                        st.hist_index = i;
                    }
                    self.render(prompt, st, true);
                    match other {
                        Key::Left | Key::Ctrl('b') => {
                            if st.pos > 0 {
                                st.pos = prev_char_boundary(&st.line, st.pos);
                                self.render(prompt, st, true);
                            }
                        }
                        Key::Right | Key::Ctrl('f') => {
                            if st.pos < st.line.len() {
                                st.pos = next_char_boundary(&st.line, st.pos);
                                self.render(prompt, st, true);
                            }
                        }
                        Key::Home | Key::Ctrl('a') => {
                            st.pos = 0;
                            self.render(prompt, st, true);
                        }
                        Key::End | Key::Ctrl('e') => {
                            st.pos = st.line.len();
                            self.render(prompt, st, true);
                        }
                        _ => {}
                    }
                    return None;
                }
            }
        }
    }

    /// Filename completion (Tab), cycling through candidates.
    fn complete(&mut self, prompt: &str, st: &mut LineState) -> Option<ReadResult> {
        let (start, candidates) = filename_candidates(&st.line, st.pos);
        if candidates.is_empty() {
            out_write("\x07");
            return None;
        }
        if candidates.len() == 1 {
            let c = &candidates[0];
            st.line.replace_range(start..st.pos, c);
            st.pos = start + c.len();
            self.render(prompt, st, true);
            return None;
        }
        let orig_line = st.line.clone();
        let orig_pos = st.pos;
        let mut i = 0usize;
        loop {
            if i < candidates.len() {
                let c = &candidates[i];
                let mut l = orig_line.clone();
                l.replace_range(start..orig_pos, c);
                st.line = l;
                st.pos = start + c.len();
            } else {
                out_write("\x07");
                st.line = orig_line.clone();
                st.pos = orig_pos;
            }
            self.render(prompt, st, true);
            let key = self.read_key();
            match key {
                Key::Tab => {
                    i = (i + 1) % (candidates.len() + 1);
                }
                Key::Esc => {
                    st.line = orig_line;
                    st.pos = orig_pos;
                    self.render(prompt, st, true);
                    return None;
                }
                Key::Char(c) => {
                    st.line.insert(st.pos, c);
                    st.pos += c.len_utf8();
                    self.render(prompt, st, true);
                    return None;
                }
                Key::Enter => {
                    self.render(prompt, st, false);
                    out_write("\x1b[?2004l\r\n");
                    return Some(ReadResult::Line(st.line.clone()));
                }
                Key::Ctrl('c') => {
                    out_write("\x1b[?2004l\r\n");
                    return Some(ReadResult::Interrupted);
                }
                _ => return None,
            }
        }
    }
}

const BREAK_CHARS: &[char] = &[
    ' ', '\t', '\n', '"', '\\', '\'', '`', '@', '$', '>', '<', '=', ';', '|', '&', '{', '(',
];

fn filename_candidates(line: &str, pos: usize) -> (usize, Vec<String>) {
    // Find the start of the word, honouring backslash escapes.
    let before = &line[..pos];
    let chars: Vec<(usize, char)> = before.char_indices().collect();
    let mut start = 0;
    let mut i = chars.len();
    while i > 0 {
        let (idx, c) = chars[i - 1];
        if BREAK_CHARS.contains(&c) {
            // escaped?
            let mut bs = 0;
            let mut j = i - 1;
            while j > 0 && chars[j - 1].1 == '\\' {
                bs += 1;
                j -= 1;
            }
            if c != '\\' && bs % 2 == 1 {
                i -= 1;
                continue;
            }
            if c == '\\' {
                i -= 1;
                continue;
            }
            start = idx + c.len_utf8();
            break;
        }
        i -= 1;
    }
    let word = &before[start..];
    let mut unescaped = String::new();
    let mut it = word.chars();
    while let Some(c) = it.next() {
        if c == '\\' {
            if let Some(n) = it.next() {
                unescaped.push(n);
            }
        } else {
            unescaped.push(c);
        }
    }
    let (dir_part, file_prefix) = match unescaped.rfind('/') {
        Some(i) => (unescaped[..=i].to_string(), unescaped[i + 1..].to_string()),
        None => (String::new(), unescaped.clone()),
    };
    let dir_path = if dir_part.is_empty() {
        std::path::PathBuf::from(".")
    } else if let Some(rest) = dir_part.strip_prefix("~/") {
        crate::paths::home_dir().unwrap_or_default().join(rest)
    } else {
        std::path::PathBuf::from(&dir_part)
    };
    let mut names: Vec<String> = Vec::new();
    if let Ok(rd) = fs::read_dir(&dir_path) {
        for entry in rd.flatten() {
            let name = entry.file_name().to_string_lossy().into_owned();
            if name.starts_with(&file_prefix) {
                let mut display = name.clone();
                if let Ok(md) = fs::metadata(entry.path()) {
                    if md.is_dir() {
                        display.push('/');
                    }
                }
                names.push(display);
            }
        }
    }
    names.sort();
    let candidates = names
        .into_iter()
        .map(|n| {
            let full = format!("{}{}", dir_part, n);
            let mut esc = String::new();
            for c in full.chars() {
                if BREAK_CHARS.contains(&c) {
                    esc.push('\\');
                }
                esc.push(c);
            }
            esc
        })
        .collect();
    (start, candidates)
}

fn prev_char_boundary(s: &str, pos: usize) -> usize {
    let mut p = pos.saturating_sub(1);
    while p > 0 && !s.is_char_boundary(p) {
        p -= 1;
    }
    p
}

fn next_char_boundary(s: &str, pos: usize) -> usize {
    let mut p = pos + 1;
    while p < s.len() && !s.is_char_boundary(p) {
        p += 1;
    }
    p.min(s.len())
}

/// Start of the word before `pos`, where `sep` identifies separators.
fn word_start(s: &str, pos: usize, sep: fn(char) -> bool) -> usize {
    let chars: Vec<(usize, char)> = s[..pos].char_indices().collect();
    let mut i = chars.len();
    while i > 0 && sep(chars[i - 1].1) {
        i -= 1;
    }
    while i > 0 && !sep(chars[i - 1].1) {
        i -= 1;
    }
    if i == chars.len() {
        pos
    } else if i < chars.len() {
        chars[i].0
    } else {
        pos
    }
}

/// End of the word after `pos` (alphanumeric words).
fn word_end(s: &str, pos: usize) -> usize {
    let rest: Vec<(usize, char)> = s[pos..].char_indices().collect();
    let mut i = 0;
    while i < rest.len() && !rest[i].1.is_alphanumeric() {
        i += 1;
    }
    while i < rest.len() && rest[i].1.is_alphanumeric() {
        i += 1;
    }
    if i < rest.len() {
        pos + rest[i].0
    } else {
        s.len()
    }
}

fn out_write(s: &str) {
    let mut out = io::stdout();
    let _ = out.write_all(s.as_bytes());
    let _ = out.flush();
}
