    /// Incremental reverse history search (Ctrl-R).
    fn reverse_search(
        &mut self,
        prompt: &str,
        st: &mut LineState,
        raw: &sys::termios,
    ) -> Option<ReadResult> {
        let orig_line = st.line.clone();
        let orig_pos = st.pos;
        let mut query = String::new();
        let mut found_line = st.line.clone();
        let mut found_pos = st.pos;
        let mut found_idx: Option<usize> = None;
        let mut failed = false;
        let render = |ed: &Editor, st: &mut LineState, q: &str, failed: bool, l: &str, p: usize| {
            let sp = format!(
                "({}reverse-i-search)`{}': ",
                if failed { "failed " } else { "" },
                q
            );
            let display = if ed.colors() {
                highlight(l, &ed.settings)
            } else {
                l.to_string()
            };
            ed.render_text(&sp, l, &display, p, None, &mut st.old);
        };
        render(self, st, &query, failed, &found_line, found_pos);
        loop {
            let key = self.read_key();
            match key {
                Key::Char(c) => {
                    query.push(c);
                    let start = found_idx.unwrap_or(self.history.len().saturating_sub(1));
                    match self.history.search(&query, start, true) {
                        Some((i, p)) => {
                            found_idx = Some(i);
                            found_line = self.history.get(i).cloned().unwrap_or_default();
                            found_pos = p;
                            failed = false;
                        }
                        None => failed = true,
                    }
                    render(self, st, &query, failed, &found_line, found_pos);
                }
                Key::Backspace | Key::Ctrl('h') => {
                    query.pop();
                    render(self, st, &query, failed, &found_line, found_pos);
                }
                Key::Ctrl('r') => {
                    let start = match found_idx {
                        Some(0) => {
                            failed = true;
                            render(self, st, &query, failed, &found_line, found_pos);
                            continue;
                        }
                        Some(i) => i - 1,
                        None => self.history.len().saturating_sub(1),
                    };
                    match self.history.search(&query, start, true) {
                        Some((i, p)) => {
                            found_idx = Some(i);
                            found_line = self.history.get(i).cloned().unwrap_or_default();
                            found_pos = p;
                            failed = false;
                        }
                        None => failed = true,
                    }
                    render(self, st, &query, failed, &found_line, found_pos);
                }
                Key::Ctrl('g') | Key::Esc => {
                    st.line = orig_line;
                    st.pos = orig_pos;
                    self.render(prompt, st, true);
                    return None;
                }
                Key::Ctrl('c') => {
                    self.move_to_end(st);
                    out_write("\x1b[?2004l\r\n");
                    return Some(ReadResult::Interrupted);
                }
                other => {
                    st.line = found_line;
                    st.pos = found_pos;
                    // The default prompt is restored without redrawing yet.
                    st.old = self.layout(prompt, &st.line, st.pos, None);
                    st.dirty_prompt = true;
                    return self.dispatch(other, prompt, st, raw);
                }
            }
        }
    }

