    /// Numeric argument entered with Meta-digit.
    fn digit_argument(
        &mut self,
        first: char,
        prompt: &str,
        st: &mut LineState,
        raw: &sys::termios,
    ) -> Option<ReadResult> {
        let mut arg = if first == '-' {
            "-".to_string()
        } else {
            first.to_string()
        };
        let shown = |a: &str| -> String {
            if a == "-" {
                "-1".to_string()
            } else {
                a.to_string()
            }
        };
        loop {
            let p = format!("(arg: {}) ", shown(&arg));
            let display = if self.colors() {
                highlight(&st.line, &self.settings)
            } else {
                st.line.clone()
            };
            let (line, pos) = (st.line.clone(), st.pos);
            self.render_text(&p, &line, &display, pos, None, &mut st.old);
            let key = self.read_key();
            match key {
                Key::Meta(d) | Key::Char(d) if d.is_ascii_digit() => {
                    if arg == "0" {
                        arg.clear();
                    }
                    arg.push(d);
                }
                other => {
                    let n: i64 = match arg.as_str() {
                        "-" => -1,
                        a => a.parse().unwrap_or(1),
