#[cfg(test)]
mod tests {
    use super::*;

    fn settings() -> Settings {
        Settings {
            fix: 10,
            base: 10,
            angle: AngleUnit::Degree,
        }
    }

    fn eval(s: &str) -> Result<f64, CalcError> {
        eval_math_expression(s, Some(0.0), &settings())
    }

    #[test]
    fn arithmetic_and_precedence() {
        assert_eq!(eval("1+2*3").unwrap(), 7.0);
        assert_eq!(eval("2^3^2").unwrap(), 512.0);
        assert_eq!(eval("-2^2").unwrap(), 4.0);
        assert_eq!(eval("2**3").unwrap(), 8.0);
        assert_eq!(eval("10%4*3").unwrap(), 6.0);
        assert_eq!(eval("3!").unwrap(), 6.0);
        assert_eq!(eval("!5").unwrap(), 1.0);
    }

    #[test]
    fn implicit_multiplication_and_parens() {
        assert_eq!(eval("2(3)").unwrap(), 6.0);
        assert_eq!(eval("(2)(3)").unwrap(), 6.0);
        assert_eq!(eval("1+(2").unwrap(), 3.0);
        assert_eq!(eval("1 2 3").unwrap(), 123.0);
        assert_eq!(eval(")"), Err(mismatched()));
        assert_eq!(eval("(2)3"), Err(too_few_operands()));
    }

    #[test]
    fn functions_and_constants() {
        assert_eq!(eval("sin(30)").unwrap(), 0.5);
        assert_eq!(eval("log(8,2)").unwrap(), 3.0);
        assert_eq!(eval("nroot(27,3)").unwrap(), 3.0);
        assert_eq!(eval("2pi").unwrap(), round_to_fix(2.0 * std::f64::consts::PI, 10));
        assert_eq!(
            eval("sin30"),
            Err(CalcError::Syntax("Function 'sin' expected parentheses".into()))
        );
        assert_eq!(
            eval("x1"),
            Err(CalcError::Syntax("Unexpected character 'x1'".into()))
        );
        assert_eq!(eval("sqrt(-1)"), Err(CalcError::Domain));
    }

    #[test]
    fn errors() {
        assert_eq!(eval("1/0"), Err(CalcError::DivideByZero));
        assert_eq!(eval("10^309"), Err(CalcError::TooLarge));
        assert_eq!(
            eval("log(8,,2)"),
            Err(CalcError::Syntax("Empty argument".into()))
        );
        assert_eq!(eval("1+(2,3)"), Err(mismatched()));
        assert_eq!(
            eval_math_expression("_", None, &settings()),
            Err(CalcError::Syntax("No previous answer!".into()))
        );
    }
}
